package com.giovannielena.restaurant.controller;
import com.giovannielena.restaurant.dto.FoodDtos.*; import com.giovannielena.restaurant.entity.*; import com.giovannielena.restaurant.repository.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/menu") public class AdminMenuController { private final FoodItemRepository foods; private final CategoryRepository categories; public AdminMenuController(FoodItemRepository f,CategoryRepository c){foods=f;categories=c;}
 @PostMapping("/categories") public Category addCategory(@Valid @RequestBody CategoryRequest r){Category c=new Category();c.setName(r.name());c.setDescription(r.description());c.setImageUrl(r.imageUrl());c.setActive(r.active());return categories.save(c);}
 @PostMapping("/foods") public FoodItem addFood(@Valid @RequestBody FoodRequest r){Category c=categories.findById(r.categoryId()).orElseThrow(()->new IllegalArgumentException("Category not found"));FoodItem f=new FoodItem();f.setCategory(c);f.setName(r.name());f.setDescription(r.description());f.setPrice(r.price());f.setImageUrl(r.imageUrl());f.setAvailable(r.available());return foods.save(f);}
 @PutMapping("/foods/{id}") public FoodItem updateFood(@PathVariable Long id,@Valid @RequestBody FoodRequest r){FoodItem f=foods.findById(id).orElseThrow();f.setCategory(categories.findById(r.categoryId()).orElseThrow());f.setName(r.name());f.setDescription(r.description());f.setPrice(r.price());f.setImageUrl(r.imageUrl());f.setAvailable(r.available());return foods.save(f);}
 @PatchMapping("/foods/{id}/availability") public FoodItem availability(@PathVariable Long id,@RequestParam boolean value){FoodItem f=foods.findById(id).orElseThrow();f.setAvailable(value);return foods.save(f);}
}